#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    long long maxPathScore(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<long long>> dp(m, vector<long long>(n, 0));
        dp[0][0] = grid[0][0];
        for (int c = 1; c < n; ++c) dp[0][c] = dp[0][c - 1] + grid[0][c];
        for (int r = 1; r < m; ++r) dp[r][0] = dp[r - 1][0] + grid[r][0];
        for (int r = 1; r < m; ++r) {
            for (int c = 1; c < n; ++c) {
                dp[r][c] = grid[r][c] + max(dp[r - 1][c], dp[r][c - 1]);
            }
        }
        return dp[m - 1][n - 1];
    }
};

class Solution {
    public long maxPathScore(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        long[][] dp = new long[m][n];
        dp[0][0] = grid[0][0];
        for (int c = 1; c < n; c++) dp[0][c] = dp[0][c - 1] + grid[0][c];
        for (int r = 1; r < m; r++) dp[r][0] = dp[r - 1][0] + grid[r][0];
        for (int r = 1; r < m; r++) {
            for (int c = 1; c < n; c++) {
                dp[r][c] = grid[r][c] + Math.max(dp[r - 1][c], dp[r][c - 1]);
            }
        }
        return dp[m - 1][n - 1];
    }
}

var maxPathScore = function(grid) {
    const m = grid.length, n = grid[0].length;
    const dp = Array.from({length: m}, () => new Array(n).fill(0n));
    dp[0][0] = BigInt(grid[0][0]);
    for (let c = 1; c < n; c++) dp[0][c] = dp[0][c - 1] + BigInt(grid[0][c]);
    for (let r = 1; r < m; r++) dp[r][0] = dp[r - 1][0] + BigInt(grid[r][0]);
    for (let r = 1; r < m; r++) {
        for (let c = 1; c < n; c++) {
            const up = dp[r - 1][c];
            const left = dp[r][c - 1];
            dp[r][c] = BigInt(grid[r][c]) + (up > left ? up : left);
        }
    }
    return Number(dp[m - 1][n - 1]);
};
